TLM.f("Sancti/05-10",{"officium":"S. Antonini Episcopi Confessoris","rule":["vide C4;mtv","9 lectiones"],"fallback":"Commune/C4","from":{"Introitus":"Commune/C4","Lectio":"Commune/C4","Graduale":"Commune/C4","GradualeP":"Commune/C4","Tractus":"Commune/C4","Evangelium":"Commune/C4","Offertorium":"Commune/C4","Communio":"Commune/C4"},"sections":{"Introitus":[{"k":"ref","la":"Eccli 45:30"},{"k":"text","la":"Státuit ei Dóminus testaméntum pacis, et príncipem fecit eum: ut sit illi sacerdótii dígnitas in ætérnum. (Allelúja, allelúja.)"},{"k":"ref","la":"Ps 131:1"},{"k":"text","la":"Meménto, Dómine, David: et omnis mansuetúdinis ejus."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Státuit ei Dóminus testaméntum pacis, et príncipem fecit eum: ut sit illi sacerdótii dígnitas in ætérnum. (Allelúja, allelúja.)"}],"Oratio":[{"k":"text","la":"Sancti Antoníni, Dómine, Confessóris tui atque Pontíficis méritis adjuvémur: ut, sicut te in illo mirábilem prædicámus, ita in nos misericórdem fuísse gloriémur."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"ref","la":"Eccli 44:16-27; 45, 3-20"},{"k":"text","la":"Ecce sacérdos magnus, qui in diébus suis plácuit Deo, et invéntus est justus: et in témpore iracúndiæ factus est reconciliátio. Non est invéntus símilis illi, qui conservávit legem Excélsi. Ideo jurejurándo fecit illum Dóminus créscere in plebem suam. Benedictiónem ómnium géntium dedit illi, et testaméntum suum confirmávit super caput ejus. Agnóvit eum in benedictiónibus suis: conservávit illi misericórdiam suam: et invénit grátiam coram óculis Dómini. Magnificávit eum in conspéctu regum: et dedit illi corónam glóriæ. Státuit illi testaméntum ætérnum, et dedit illi sacerdótium magnum: et beatificávit illum in glória. Fungi sacerdótio, et habére laudem in nómine ipsíus, et offérre illi incénsum dignum in odórem suavitátis."}],"Graduale":[{"k":"ref","la":"Eccli 44:16"},{"k":"text","la":"Ecce sacérdos magnus, qui in diébus suis plácuit Deo."},{"k":"ref","la":"Eccli 44:20"},{"k":"text","la":"Non est invéntus símilis illi, qui conserváret legem Excélsi. Allelúja, allelúja."},{"k":"ref","la":"Ps 109:4"},{"k":"text","la":"Tu es sacérdos in ætérnum, secúndum órdinem Melchísedech. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 109:4"},{"k":"text","la":"Tu es sacérdos in ætérnum, secúndum órdinem Melchísedech. Allelúja."},{"k":"text","la":"Hic est sacérdos, quem coronávit Dóminus. Allelúja.","mark":"V"}],"Tractus":[{"k":"ref","la":"Eccli 44:16"},{"k":"text","la":"Ecce sacérdos magnus, qui in diébus suis plácuit Deo."},{"k":"ref","la":"Eccli 44:20"},{"k":"text","la":"Non est invéntus símilis illi, qui conserváret legem Excélsi."},{"k":"ref","la":"Ps 111:1-3"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis."},{"k":"text","la":"Potens in terra erit semen ejus: generátio rectórum benedicétur.","mark":"V"},{"k":"text","la":"Glória et divítiæ in domo ejus: et justítia ejus manet in sǽculum sǽculi.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 25:14-23"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis parábolam hanc: Homo péregre proficíscens vocávit servos suos, et trádidit illis bona sua. Et uni dedit quinque talénta, álii autem duo, álii vero unum, unicuíque secúndum própriam virtútem, et proféctus est statim. Abiit autem, qui quinque talénta accéperat, et operátus est in eis, et lucrátus est ália quinque. Simíliter et, qui duo accéperat, lucrátus est ália duo. Qui autem unum accéperat, ábiens fodit in terram, et abscóndit pecúniam dómini sui. Post multum vero témporis venit dóminus servórum illórum, et pósuit ratiónem cum eis. Et accédens qui quinque talénta accéperat, óbtulit ália quinque talénta, dicens: Dómine, quinque talénta tradidísti mihi, ecce, ália quinque superlucrátus sum. Ait illi dóminus ejus: Euge, serve bone et fidélis, quia super pauca fuísti fidélis, super multa te constítuam: intra in gáudium dómini tui. Accéssit autem et qui duo talénta accéperat, et ait: Dómine, duo talénta tradidísti mihi, ecce, ália duo lucrátus sum. Ait illi dóminus ejus: Euge, serve bone et fidélis, quia super pauca fuísti fidélis, super multa te constítuam: intra in gáudium dómini tui."}],"Offertorium":[{"k":"ref","la":"Ps 88:21-22"},{"k":"text","la":"Invéni David servum meum, óleo sancto meo unxi eum: manus enim mea auxiliábitur ei, et bráchium meum confortábit eum. (Allelúja.)"}],"Secreta":[{"k":"text","la":"Sancti tui, quǽsumus, Dómine, nos ubíque lætíficant: ut, dum eórum mérita recólimus, patrocínia sentiámus."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Luc 12:42"},{"k":"text","la":"Fidélis servus et prudens, quem constítuit dóminus super famíliam suam: ut det illis in témpore trítici mensúram. (Allelúja.)"}],"Postcommunio":[{"k":"text","la":"Præsta, quǽsumus, omnípotens Deus: ut, de percéptis munéribus grátias exhibéntes, intercedénte beáto Antoníno Confessóre tuo atque Pontífice, benefícia potióra sumámus."},{"k":"macro","name":"Per Dominum"}]},"hr":{"bd20ee7c87c78aa5":{"t":"Sir 45, 30, Ps 131, 1\n(Sir 45, 30) Sklopio je Gospodin s njime savez mira učinio ga knezom da zauvijek bude u svećeničkom dostojanstvu. <i>Aleluja</i>, <i>aleluja</i>.\n(Ps 131, 1) Spomeni se, Gospodine, Davida i sve njegove krotkosti.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Sir 45, 30) Sklopio je Gospodin s njime savez mira učinio ga knezom da zauvijek bude u svećeničkom dostojanstvu. <i>Aleluja</i>, <i>aleluja</i>.","kn":"(Grkv. 45, 30). Gospodin je sklopio s njime savez mira i učinio ga knezom, da zauvijek bude u svećeničkom dostojanstvu. (Ps. 131, 1). Sjeti se, Gospodine, Davida i sve njegove pobožnosti. Slava Ocu. Gospodin ...","knRef":"Kniewald 1942, str. 478–479 (snimka 240) (OCR)"},"194da4b116f71a62":{"t":"<i>Pomolimo se</i>.\nPomagale nam, Gospodine, zasluge svetoga Antonina priznavaoca tvoga i biskupa, da se tako dičimo tvojim milosrđem prema nama kao što te slavimo zbog divnoga tvog djelovanja u njemu.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Pomogle nam. Gospodine, zasluge svetog Antonina, p.riznavaoca Tvoga i biskupa te, kao što si se proslavio u njemu, tako i nama, budi milosrdan, po G. n.","knRef":"Kniewald 1942, str. 570–571 (snimka 286) (OCR)"},"95ddbdede28f22c8":{"t":"Sir 44, 16-27; 45, 3-20\nČitanje knjige Mudrosti. Evo velikog svećenika,koji se za svoga života svidio Bogu i bio je pravedan, te je postao pomirnikom u vrijeme srdžbe. Nitko se ne nađe tko bi kao on izvršavao zakon Svevišnjega. I jer mu se Gospodin zavjeri, učini da uzraste kao njegov narod. Izlio je na njega blagoslov svih naroda i nad njim je potvrdio svoj zavjet. Odlikovao ga je svojim blagoslovima, očuvao mu svoje milosrđe te je stekao milost pred Gospodinom. Proslavio ga je pred kraljevima i udijelio mu vijenac slave. Sklopio je s njim vječni zavjet i predao mu veliko svećenstvo. Usrećio ga je slavom da vrši svećeničku službu i blagoslivlja u njegovo ime i prinosi mu dostojan miomirisni kad.","kn":"Čitanje Knjige mudrosti (Crkv. 44, 16-27. 45, 3-20). Evo velikog svećenika, koji se za svoga života svidio Bogu 1 nađen je pravednim, te je postao pomirnikom u vrijeme srdžbe. Nitko se' ne nađe, tko bi kao on izvršivao zakon Svevišnjega. I jer. mu se Gospodin zavjeri, učini, da uzraste kao njegov narod. Izlio je na njega blagoslov svih naroda i nad njim je potvrdio svoj zavjet. Odlikovao ga je svojim blagoslovima, očuvao mu svoje milosrđe, te je stekao milost pred Gospodinom. Proslavio ga je pred kraljevima i udijelio mu vijenac slave. Sklopio je B njim vječni zavjet i predao mu veliko svećeništvo. Usrećio ga je slavom, da vrši svećeničku službu i blagosivlja u njegovo ime i prinosi mu dostojan miomirisni kad. t","knRef":"Kniewald 1942, str. 808–809 (snimka 405) (OCR)"},"9774d0e78b0dcdae":{"t":"Ps 109, 4\n<i>Aleluja</i>, <i>aleluja</i>.\nTi si svećenik dovijeka po redu Melkisedekovu. <i>Aleluja</i>.\nOvo je svećenik kojega je okrunio Gospodin. <i>Aleluja</i>.","kn":"Aleluja, aleluja! (Ps. 109, 4). Za uvijek ti si svećenik po redu Melkizeđekovu, aleluja. Ovo je svećenik, icoga je okrunio Gospodin, aleluja!","knRef":"Kniewald 1942, str. 808–809 (snimka 405) (OCR)"},"b87a2aadbcf6e431":{"t":"Mt 25, 14-23\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme reče Isus svojim učenicima ovu usporedbu: Čovjek koji kreće na put pozove svoje sluge i preda im svoj imetak. Jednomu dade pet talenata, drugome dva, a trećemu jedan: svakomu prema njegovoj sposobnosti. I odmah otputuje. Onaj koji je primio pet talenata ode da s njima radi i stječe drugih pet. Tako i koji je primio dva steče s njima druga dva. A koji je primio jedan, ode, zakopa i sakrije novac svoga gospodara. Poslije dugo vremena dođe gospodar onih slugu i zatraži od njih račun. I pristupi onaj koji je primio pet talenata, donese drugih pet talenata i reče: Gospodaru, predao si mi pet talenata. Stekao sam s njima drugih pet. Gospodar mu odgovori: Dobro, slugo dobri i vjerni, jer si bio vjeran u malom, postavit ću te nad mnogim: Uđi u veselje svoga gospodara! A pristupi i onaj koji je primio dva talenta i reče: Gospodaru, predao si mi dva talenta. Stekao sam s njima druga dva. Gospodar mu odgovori: Dobro, slugo dobri i vjerni, jer si bio vjeran u malome, postavit ću te nad mnogim: Uđi u veselje svoga gospodara!","kn":"t Slijedi sveto evanđelje po Mateju (25, 14-23), U ono vrijeme reče Isus svojim učenicima ovu prisjpodobu; Čovjek, koji kreće na put, pozove svoje sluge i preda im svoj imetak. Jednomu dade pet talenata, drugomu dva, a trećemu jedan; svakomu prema njegovoj sposobnosti. I odmah otputuje. Onaj, koji je primio pet talenata, ode, da s njima radi i steče drugih pet. Tako i koji je primio dva, steče s njima druga dva. A koji je primio jedan, ode, zakopa i sakrije novac svoga gospodara. Poslije dugo vremena dođe gospodar onih slugu i zatraži od njih račun. I pristupi onaj, koji je primio pet talenata, donese drugih pet talenata i reče: Gospodaru, predao si mi pet talenata. Stekao sam s njima drugih pet. Gospodar mu odgovori: Dobro, slugo dobri i vjerni, jer si bio vjeran u malom, postavit ću te nad mnogim: Uđi u veselje svoga gospodara! A pristupi i onaj, koji je primio dva talenta i reče: Gospodaru, predao si mi dva talenta. Stekao sam s njima druga dva. Gospodar mu odgovori; Dobro, slugo dobri i vjerni, jer si bio vjeran u malom, postavit ću te nad mnogim; Uđi u veselje svoga gospodara! Vjerujem.","knRef":"Kniewald 1942, str. 626–627 (snimka 314) (OCR)"},"5ebabe64ecb9d6c4":{"t":"Ps 88, 21-22\nNašao sam Davida, slugu svojega, pomazao sam ga svojim svetim uljem. S njim će biti ruka moja i krijepit će ga desnica moja. <i>Aleluja</i>.","kn":"(Ps. 88, 21, 22). Izabrao sam Davida za slugu svoga i pomazao sam ga mojim svetim uuem. Moja će ga ruka i mišica će ga moja krijepiti, aleluja. .","knRef":"Kniewald 1942, str. 560–561 (snimka 281) (OCR)"},"3171212e73cd052d":{"t":"Neka nas, molimo, Gospodine, tvoji sveti posvuda razveseljuju, da osjetimo njihovu zaštitu dok štujemo njihove zasluge.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Neka nas, molimo, Gospodine, sveti Tvoji posvuda razveseljuju, da osjetimo njihovu zaštitu spominjući se njihovih zasluga, po G. n.","knRef":"Kniewald 1942, str. 810–811 (snimka 406) (OCR)"},"e3481c16f40c8803":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – On se poslije svojeg uskrsnuća svim svojim učenicima javno ukazao i pred njihovim se očima uzdigao na nebo, da nas učini dionicima svoga božanstva. – I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:","kn":"Predslovlje: Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti. Oče svemogući, vječni Bože, po Kristu, Gospodinu našem, jer On se poslije svoga uskrsnuća očito ukazao svim svojim učenicima 1 njima se na očigled uzđignuo na nebo, da tako, po njegovom daru, budemo zajedničari Božanstva Njegova. I toga radi pjevamo pjesmu slave Tvoje s anđelima i B arkanđelima, s prijestolima i s gospodstvima, sa svom silom nebeske vojske bez prestanka govoreći:","knRef":"Kniewald 1942, str. 336–337 (snimka 169) (OCR)"},"18d15f4c3171d6cb":{"t":"Lk 12, 42\nEvo vjernog i razboritog sluge koga je postavio Gospodin nad svojom obitelji, da im na vrijeme daje za hranu pšenicu koja im pripada. <i>Aleluja</i>.","kn":"(Lk. 12, 42). Evo razboritog i vjernog upravitelja, koga postavi Gospodin nad družinom svojom, da im na vrijeme daje hranu, koja im pripada.","knRef":"Kniewald 1942, str. 524–525 (snimka 263) (OCR)"},"7f4184488ddb1529":{"t":"<i>Pomolimo se</i>.\nPodaj, molimo, svemogući Bože, da, dok ti na primljenim darovima zahvaljujemo, zagovorom tvoga blaženoga priznavaoca i biskupa Antonina još u obilnijoj mjeri primimo tvoja dobročinstva.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Podaj, molimo, svemogući Bože, da Ti na primljenim darovima zahvaljujemo i da zagovorom Tvoga svetoga priznavaoca i pape (biskupa) I., još u obilnijoj mjeri primimo Tvoja dobročinstva, po G. n.","knRef":"Kniewald 1942, str. 810–811 (snimka 406) (OCR)"},"1a0a565aa39e4fe3":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno da tebe, Gospodine, u svako doba, a osobito <i>u ovo</i> svečanije slavimo, kad je Krist žrtvovan, naše vazmeno Janje. On je naime pravo janje koje oduze grijehe svijeta. Svojom smrću on je uništio našu smrt i svojim uskrsnućem obnovio naš život. – I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:","kn":"j Uistinu je dostojno i pravedno, pravo i spaso- I doba, ali osobito svečano na - današnji dan, (u ovo vrijeme), kad je žrtvovano naše vazmeno Janje, I Isukrst; jer On je pravo janje, koje je uzelo grijehe : svojim je uskrsnućem obnovio naš ž^vot. Zato pje- I vamo pjesmu Tvoje slave s anđelima i s arkanđe lima, s. prijestolima i s gospodstvima i sa svom silom nebeske vojske govoreći bez prestanka:","knRef":"Kniewald 1942, str. 20–21 (snimka 11) (OCR)"}},"variants":{"paschal":{"Graduale":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 109:4"},{"k":"text","la":"Tu es sacérdos in ætérnum, secúndum órdinem Melchísedech. Allelúja."},{"k":"text","la":"Hic est sacérdos, quem coronávit Dóminus. Allelúja.","mark":"V"}]}}});
